//! Checked native textarea defaults share DOM replacement and Reset state.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><textarea id=area name=q>A\r\n😀Z</textarea><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://textarea-default.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn textarea_default_value_canonical_descriptor_and_pristine_normalization(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'defaultValue');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get defaultValue'||a.set.name!=='set defaultValue'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'defaultValue'))throw 'canonical defaultValue';var old=x.firstChild,calls=0;x.defaultValue={toString:function(){calls++;return 'B\r\n😀\rC';}};if(calls!==1||x.defaultValue!=='B\r\n😀\rC'||x.textContent!==x.defaultValue||x.value!=='B\n😀\nC'||x.textLength!==6||x.firstChild===old||old.parentNode!==null||old.data!=='A\n😀Z')throw 'pristine default transaction';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();assert!(!f.controls[&n].dirty_value);}
#[test]
fn textarea_default_value_dirty_editor_and_native_reset_follow_new_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='kept';");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}run(&mut d,&mut f,&mut p,r#"x.defaultValue='new\r\n😀';if(x.defaultValue!=='new\r\n😀'||x.value!=='kept')throw 'dirty value changed';"#);let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset),(3,1,2));assert!(c.dirty_value);let owner=c.owner.unwrap();f.reset_in_document(&d,owner).unwrap();p.begin_job();run(&mut d,&mut f,&mut p,r#"if(x.value!=='new\n😀'||x.textLength!==6||x.defaultValue!=='new\r\n😀')throw 'reset new default';"#);assert!(!f.controls[&n].dirty_value);}
#[test]
fn textarea_default_value_text_content_alias_and_empty_replacement(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area');x.textContent='alias\r\n😀';if(x.defaultValue!=='alias\r\n😀'||x.value!=='alias\n😀')throw 'pristine textContent';x.value='dirty';x.textContent='reset';if(x.defaultValue!=='reset'||x.value!=='dirty')throw 'dirty textContent';x.defaultValue='';if(x.firstChild!==null||x.defaultValue!==''||x.value!=='dirty')throw 'empty default';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();f.reset_in_document(&d,f.controls[&n].owner.unwrap()).unwrap();assert_eq!(f.controls[&n].value.text(),"");}

#[test]
fn textarea_default_value_saved_authority_conversion_and_ordinary_overrides(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'defaultValue'),get=a.get,set=a.set,calls=0;set.call(x,null);if(x.defaultValue!=='null'||x.value!=='null')throw 'DOMString null';set.call(x);if(x.defaultValue!=='undefined')throw 'missing undefined';var marker={};try{set.call(x,{toString:function(){calls++;x.setAttribute('data-side','kept');throw marker;}});throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(calls!==1||x.defaultValue!=='undefined'||x.getAttribute('data-side')!=='kept')throw 'conversion effects';try{set.call(x,Symbol('x'));throw 'missing symbol failure';}catch(e){if(!(e instanceof TypeError))throw e;}Object.defineProperty(P,'defaultValue',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.defaultValue='override';set.call(x,'native');if(x.defaultValue!=='author'||get.call(x)!=='native'||x.getAttribute('data-author')!=='override')throw 'saved accessor authority';Object.defineProperty(x,'defaultValue',{value:'own',writable:true,configurable:true});set.call(x,'saved');if(x.defaultValue!=='own'||get.call(x)!=='saved')throw 'saved own';delete x.defaultValue;delete P.defaultValue;if(x.defaultValue!==undefined)throw 'deleted accessor resurrected';Object.defineProperty(P,'defaultValue',a);var C=HTMLTextAreaElement;delete window.HTMLTextAreaElement;if(!(x instanceof C)||get.call(x)!=='saved')throw 'saved constructor';"#);}
#[test]
fn textarea_default_value_wrong_brand_and_missing_native_state_precede_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'defaultValue'),calls=0;for(var bad of [{},document,document.getElementById('neighbor'),Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}var owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','textarea');try{a.set.call(inert,{toString:function(){calls++;return 'bad';}});throw 'fake native default';}catch(e){if(e.name!=='NotSupportedError'||e.message.indexOf('admitted native default state')===-1)throw e;}if(calls||x.defaultValue!=='A\n😀Z')throw 'brand coerced';"#);}
#[test]
fn textarea_default_value_observers_live_children_and_reentrant_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),old=x.firstChild,list=x.childNodes,watch=new MutationObserver(function(){}),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};watch.observe(x,{childList:true});var calls=0;x.defaultValue={toString:function(){calls++;x.defaultValue='inner';return 'outer\r\n😀';}};var r=watch.takeRecords();if(calls!==1||x.defaultValue!=='outer\r\n😀'||x.value!=='outer\n😀'||events||list.length!==1||list[0]!==x.firstChild||old.parentNode!==null||r.length!==2||r[0].removedNodes[0]!==old||r[1].addedNodes[0]!==x.firstChild)throw 'real atomic replace records';var prior=x.firstChild;x.textContent='alias';r=watch.takeRecords();if(r.length!==1||r[0].removedNodes[0]!==prior||r[0].addedNodes[0]!==x.firstChild||x.value!=='alias')throw 'textContent observer alias';"#);}
#[test]
fn textarea_default_value_dirty_copy_detach_reconnect_independent_reset(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area');x.value='dirty';x.defaultValue='reset\r\n😀';var copy=x.cloneNode(true);if(copy.value!=='dirty'||copy.defaultValue!=='reset\r\n😀')throw 'dirty copied state';copy.defaultValue='copy default';x.parentNode.removeChild(x);x.defaultValue='detached';if(x.value!=='dirty'||copy.value!=='dirty'||x.defaultValue!=='detached'||copy.defaultValue!=='copy default')throw 'independent defaults';document.getElementById('form').appendChild(x);if(x.form!==document.getElementById('form')||x.value!=='dirty'||x.defaultValue!=='detached')throw 'reconnected state';"#);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")&&f.controls[n].owner.is_some()).unwrap();f.reset_in_document(&d,f.controls[&n].owner.unwrap()).unwrap();assert_eq!(f.controls[&n].value.text(),"detached");}
#[test]
fn textarea_default_value_full_utf16_bound_and_oversize_raw_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.defaultValue='{}';if(x.textLength!==4096||x.value!==x.defaultValue)throw 'full UTF16 default';","😀".repeat(2048)));let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in [format!("x.defaultValue='{}';","😀".repeat(2049)),r"x.defaultValue='\uD800';".into(),r"x.textContent='\uDC00';".into()]{p.begin_job();assert!(p.runtime.execute(&source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.begin_job();run(&mut d,&mut f,&mut p,r#"x.defaultValue='recovered\r\n';if(x.value!=='recovered\n')throw 'fresh native default recovery';"#);}
#[test]
fn textarea_default_value_resource_refusal_preserves_dom_editor_and_reset_default(){for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='dirty';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("textarea")};let nodes=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();let capture=|f:&Forms|{let c=&f.controls[&n];(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)};let native=capture(&f);let retained=p.state.retained_limit;let node_limit=p.state.node_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_default_value_set(object,&Value::String("replacement".into())).is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!((p.state.retained,p.state.dom_commits),before);assert_eq!(capture(&f),native);p.state.retained_limit=retained;p.state.node_limit=node_limit;p.state.execution_deadline=None;f.reset_in_document(&d,f.controls[&n].owner.unwrap()).unwrap();assert_eq!(f.controls[&n].value.text(),"A\n😀Z");p.begin_job();run(&mut d,&mut f,&mut p,"x.defaultValue='fresh';if(x.value!=='fresh')throw 'fresh default recovery';");}}
#[test]
fn textarea_default_value_saved_child_origin_refuses_before_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'defaultValue'),calls=0;a.set.call(x,'same origin');");p.set_location(&crate::navigation::address("https://foreign-textarea-default.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("a.set.call(x,{toString:function(){calls++;return 'foreign';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://textarea-default.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.defaultValue!=='same origin')throw 'foreign conversion';a.set.call(x,'recovered');if(x.value!=='recovered')throw 'origin recovery';");}

#[test]
fn textarea_default_value_guarded_child_mutations_do_not_stale_native_reset(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.defaultValue='admitted';x.value='dirty';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["x.firstChild.data='unprepared';","x.firstChild.appendData('unprepared');","x.innerHTML='\\udfff\\ud800unprepared';","x.appendChild(document.createTextNode('unprepared'));"]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");if !source.contains("createTextNode"){assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.begin_job();run(&mut d,&mut f,&mut p,"if(x.defaultValue!=='admitted'||x.value!=='dirty')throw 'stale default after guarded mutation';");}let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();f.reset_in_document(&d,f.controls[&n].owner.unwrap()).unwrap();assert_eq!(f.controls[&n].value.text(),"admitted");}
